<?php
require_once __DIR__.'/../includes/functions.php';require_once __DIR__.'/../includes/auth.php';
if(!auth_check()||!preview_original_user())access_deny(403,'central_preview',__t('Central administration with verified two-step sign-in is required.','مدیریت مرکزی با تأیید دو مرحله‌ای لازم است.','مرکزي مدیریت او دوه مرحلې تایید اړین دی.'));
$error='';
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
    try{
        if(!csrf_verify($_POST['csrf_token']??''))throw new RuntimeException('Invalid form session.',403);
        $action=$_POST['action']??'';
        if($action==='stop'){preview_stop();redirect(BASE_URL.'admin/office_2.php?tab=users');}
        if($action!=='start')throw new InvalidArgumentException('Invalid preview action.');
        $selection=$_POST['selection']??'';if(!is_string($selection)||!preg_match('/^([1-9][0-9]*):([1-9][0-9]*)$/D',$selection,$m))throw new InvalidArgumentException(__t('Choose a user and branch.','یوزر و شعبه را انتخاب کنید.','کارن او څانګه وټاکئ.'));
        preview_start((int)$m[1],(int)$m[2]);redirect(BASE_URL.'index.php');
    }catch(Throwable $e){http_response_code($e->getCode()===403?403:422);$error=public_error($e);}
}
$selectedUser=filter_var($_GET['user_id']??0,FILTER_VALIDATE_INT)?:0;$choices=[];
foreach($pdo->query("SELECT id,username,fullname,role,status,shop_id FROM users WHERE role NOT IN ('superadmin','super_admin') ORDER BY fullname,id")->fetchAll() as $u){
    if($selectedUser&&(int)$u['id']!==$selectedUser)continue;if(!access_account_available($u))continue;
    foreach(domain_branches($u) as $branch)$choices[]=['value'=>$u['id'].':'.$branch['id'],'label'=>$u['fullname'].' · '.$u['username'].' — '.$branch['name'].' · '.$branch['city'],'user'=>(int)$u['id']];
}
$preview=preview_state();
?><!doctype html><html lang="<?= sanitize(get_current_lang()) ?>" dir="<?= sanitize(get_current_dir()) ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= __t('Read-only user preview','پیش‌نمایش فقط‌خواندنی یوزر','د کارن کتنه') ?></title><link rel="stylesheet" href="<?= BASE_URL ?>assets/vendor/vazirmatn/font.css"><link rel="stylesheet" href="<?= BASE_URL ?>assets/css/style.css?v=<?= APP_VERSION ?>"><link rel="stylesheet" href="<?= BASE_URL ?>assets/css/branding.css?v=<?= APP_VERSION ?>"></head><body class="modern-app" style="padding:24px;max-width:900px;margin:auto"><main class="card modern-form"><h1><?= __t('Preview the workspace as a user','پیش‌نمایش فضای کاری به‌شکل یک یوزر','د کارن کاري ځای کتنه') ?></h1><p><?= __t('This does not replace your administrator identity. The selected user\'s menus and permissions are shown, but every POST change and quota consumption is blocked.','هویت مدیر شما تغییر نمی‌کند. منوها و صلاحیت‌های یوزر انتخاب‌شده دیده می‌شود، اما تمام تغییرات POST و مصرف سهمیه متوقف است.','ستاسو د مدیر پېژندنه نه بدلېږي؛ ټول بدلونونه او ونډه بنده ده.') ?></p><?php if($preview):?><div class="alert alert-warning"><?= __t('Preview is active. Exit it from the yellow bar in the workspace, or stop it here.','پیش‌نمایش فعال است؛ از نوار زرد فضای کاری یا از همین صفحه خارج شوید.','کتنه فعاله ده؛ له کاري ځای یا له دې ځایه ووځئ.') ?></div><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="stop"><button class="btn btn-primary"><?= __t('Exit current preview','خروج از پیش‌نمایش فعلی','له اوسنۍ کتنې وتل') ?></button></form><hr><?php endif; ?><?php if($error):?><div class="alert alert-danger"><?= sanitize($error) ?></div><?php endif; ?><?php if($choices):?><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="start"><label><?= __t('User and assigned branch','یوزر و شعبهٔ تعیین‌شده','کارن او ټاکل شوې څانګه') ?><select class="form-control" name="selection" required><?php foreach($choices as $choice):?><option value="<?= $choice['value'] ?>"><?= sanitize($choice['label']) ?></option><?php endforeach ?></select></label><p><button class="btn btn-primary" type="submit"><i class="fa-solid fa-eye"></i> <?= __t('Open read-only preview','بازکردن پیش‌نمایش فقط‌خواندنی','کتنه پرانیزئ') ?></button> <a class="btn btn-secondary" href="<?= BASE_URL.'admin/office_2.php' ?>?tab=users"><?= __t('Back to Office 2','بازگشت به دفتر دو','دفتر دو ته') ?></a></p></form><?php else:?><div class="alert alert-info"><?= __t('No active assigned business user is available. Assign a branch first.','یوزر فعال با شعبهٔ تعیین‌شده وجود ندارد؛ نخست شعبه تعیین کنید.','فعال کارن او څانګه نشته؛ لومړی څانګه وټاکئ.') ?></div><?php endif; ?></main></body></html>
